return (async function() {
var b64 = "";
var mime = "image/jpeg";
var byteString = atob(b64);
var ab = new ArrayBuffer(byteString.length);
var ia = new Uint8Array(ab);
for (var j = 0; j < byteString.length; j++) ia[j] = byteString.charCodeAt(j);
var blob = new Blob([ab], {type: mime});
var fd = new FormData();
fd.append('image', blob, 'img.jpg');
var resp = await fetch('/spice/image?upload_source=20020002&need_enhance=true&aid=1231&device_platform=web', {method: 'POST', body: fd});
var data = await resp.json();
if (data.code === 0 && data.data && data.data.image_url) {
    return JSON.stringify({status: 'ok', url: data.data.image_url});
} else {
    return JSON.stringify({status: 'fail', code: data.code, msg: data.message});
}
})();
